<?php
namespace Tests\Feature;
use App\Models\{User,Customer,SalesInvoice}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class InvoiceManagementTest extends TestCase { use RefreshDatabase; private function payload(): array{return ['party_id'=>Customer::first()->id,'issue_date'=>now()->toDateString(),'due_date'=>now()->addDays(10)->toDateString(),'discount_value'=>0,'discount_type'=>'flat','tax_rate'=>0,'items'=>[['description'=>'Consulting','quantity'=>1,'unit_price'=>100,'tax_rate'=>0]]];} public function test_invoice_can_be_updated_and_recalculated(): void { $user=User::factory()->create(['role'=>'admin']);$customer=Customer::create(['name'=>'Test']);$data=$this->payload();$data['party_id']=$customer->id;$response=$this->actingAs($user)->post(route('invoices.store','sales'),$data);$invoice=SalesInvoice::latest()->first();$response->assertRedirect(route('invoices.show',['sales',$invoice]));$data['items'][0]['unit_price']=200;$this->actingAs($user)->put(route('invoices.update',['sales',$invoice]),$data);$this->assertDatabaseHas('sales_invoices',['id'=>$invoice->id,'total'=>'200.00']);$this->actingAs($user)->delete(route('invoices.destroy',['sales',$invoice]))->assertRedirect(route('invoices.index','sales'));$this->assertSoftDeleted('sales_invoices',['id'=>$invoice->id]);} }
